DECLARE n NUMBER; BEGIN
  SELECT NVL(MAX(LIST_ID), 0) + 1 INTO n FROM MERCHANT_LIST;
  EXECUTE IMMEDIATE 'DROP SEQUENCE SEQ_MERCHANT_LIST';
  EXECUTE IMMEDIATE 'CREATE SEQUENCE SEQ_MERCHANT_LIST START WITH ' || n || ' INCREMENT BY 1 NOCACHE';
END;
